products.forEach(product => {
  product.cardName = product.season === product.year
    ? `${product.team} '${String(product.year).slice(2)}`
    : product.name;
  product.imageUrl = productImageUrls[product.name] || "";
  product.alt = product.name;
});

const sizes = ["XS", "S", "M", "L", "XL", "XXL"];
const emptyCartIconUrl = "data:image/png;base64,";
const fullCartIconUrl = "https://icones.pro/wp-content/uploads/2021/05/symbole-charrette-orange.png";

let cart = normalizeCart(JSON.parse(localStorage.getItem("cart")) || []);
let undoTimer;

function normalizeCart(items) {
  return items.map(item => {
    if (typeof item === "string") {
      return { name: item, size: "M" };
    }

    return {
      name: item.name,
      size: sizes.includes(item.size) ? item.size : "M"
    };
  }).filter(item => products.some(product => product.name === item.name));
}

function sameCartItem(item, name, size) {
  return item.name === name && item.size === size;
}

function saveCart() {
  localStorage.setItem("cart", JSON.stringify(cart));
  updateCart();
}

function addToCart(name, size = "M", quantity = 1) {
  const amount = Math.max(1, Number(quantity) || 1);

  for (let i = 0; i < amount; i += 1) {
    cart.push({ name, size });
  }

  saveCart();
}

function removeFromCart(name, size = "M") {
  const index = cart.findIndex(item => sameCartItem(item, name, size));
  if (index !== -1) {
    const removed = cart.splice(index, 1)[0];
    saveCart();
    return removed;
  }

  return null;
}

function clearCart() {
  const removedItems = [...cart];
  cart = [];
  saveCart();
  return removedItems;
}

function updateCart() {
  document.querySelectorAll("#cart-count").forEach(el => {
    el.innerText = cart.length;
  });

  document.querySelectorAll("[data-cart-icon]").forEach(icon => {
    icon.src = cart.length > 0 ? fullCartIconUrl : emptyCartIconUrl;
  });
}

function priceNumber(price) {
  return Number(String(price).replace(/[^0-9.]/g, ""));
}

function formatPrice(amount) {
  return `\u20A6${Number(amount).toLocaleString("en-NG", {
    maximumFractionDigits: 0,
    minimumFractionDigits: 0
  })}`;
}

function cartItems() {
  return products.flatMap(product => {
    return sizes.map(size => {
      const quantity = cart.filter(item => sameCartItem(item, product.name, size)).length;
      return { ...product, size, quantity, subtotal: quantity * priceNumber(product.price) };
    });
  }).filter(item => item.quantity > 0);
}

function cartTotal() {
  return cartItems().reduce((total, item) => total + item.subtotal, 0);
}

function renderCartPage() {
  const list = document.getElementById("cartList");
  const total = document.getElementById("cartTotal");
  const checkout = document.getElementById("checkoutLink");
  const empty = document.getElementById("emptyCart");
  const clear = document.getElementById("clearCart");

  if (!list || !total) return;

  const items = cartItems();
  list.innerHTML = "";

  if (items.length === 0) {
    empty.innerText = "Your cart is empty.";
    total.innerText = formatPrice(0);
    checkout.classList.add("disabled");
    checkout.removeAttribute("href");
    if (clear) clear.disabled = true;
    return;
  }

  empty.innerText = "";
  checkout.classList.remove("disabled");
  checkout.setAttribute("href", "checkout.html");
  if (clear) clear.disabled = false;

  items.forEach(item => {
    const row = document.createElement("li");
    row.className = "cart-row";
    row.innerHTML = `
      <div>
        <a class="cart-item-link" href="product.html?name=${encodeURIComponent(item.name)}">${item.name}</a>
        <span>${item.brand} / ${item.type} / Size ${item.size}</span>
      </div>
      <div class="quantity-controls">
        <button type="button">-</button>
        <span>${item.quantity}</span>
        <button type="button">+</button>
      </div>
      <strong>${formatPrice(item.subtotal)}</strong>
    `;

    const buttons = row.querySelectorAll("button");
    buttons[0].addEventListener("click", () => {
      const removed = removeFromCart(item.name, item.size);
      renderCartPage();
      showCartUndo(removed ? [removed] : [], `Removed ${item.name} size ${item.size}`);
    });
    buttons[1].addEventListener("click", () => {
      addToCart(item.name, item.size);
      renderCartPage();
    });

    list.appendChild(row);
  });

  total.innerText = formatPrice(cartTotal());
}

function showCartUndo(removedItems, message) {
  const undo = document.getElementById("cartUndo");
  if (!undo || removedItems.length === 0) return;

  clearTimeout(undoTimer);
  undo.classList.add("show");
  undo.innerHTML = `
    <div class="undo-copy">
      <strong>${message}</strong>
      <span>Restore these items before the window closes.</span>
    </div>
    <button type="button">Undo</button>
    <span class="undo-progress"></span>
  `;

  undo.querySelector("button").addEventListener("click", () => {
    cart.push(...removedItems);
    saveCart();
    renderCartPage();
    undo.classList.remove("show");
    undo.innerHTML = "";
  });

  undoTimer = setTimeout(() => {
    undo.classList.remove("show");
    undo.innerHTML = "";
  }, 6000);
}

function renderCheckoutPage() {
  const list = document.getElementById("orderList");
  const total = document.getElementById("orderTotal");
  if (!list || !total) return;

  const items = cartItems();
  list.innerHTML = "";

  if (items.length === 0) {
    list.innerHTML = "<li>Your cart is empty</li>";
    total.innerText = formatPrice(0);
    return;
  }

  items.forEach(item => {
    const li = document.createElement("li");
    li.textContent = `${item.name} / Size ${item.size} x ${item.quantity} - ${formatPrice(item.subtotal)}`;
    list.appendChild(li);
  });

  total.innerText = formatPrice(cartTotal());
}

updateCart();

const toggle = document.getElementById("themeToggle");

if (toggle) {
  toggle.addEventListener("click", () => {
    document.body.classList.toggle("dark");
    localStorage.setItem("theme", document.body.classList.contains("dark"));
  });
}

if (localStorage.getItem("theme") === "true") {
  document.body.classList.add("dark");
}

document.querySelectorAll(".menu-toggle").forEach(menuToggle => {
  const navbar = menuToggle.closest(".navbar");
  const menu = navbar?.querySelector(".site-menu");

  if (!navbar || !menu) return;

  menuToggle.addEventListener("click", () => {
    navbar.classList.toggle("menu-open");
  });

  document.addEventListener("click", event => {
    if (!navbar.classList.contains("menu-open") || navbar.contains(event.target)) return;

    navbar.classList.remove("menu-open");
  });

  menu.addEventListener("click", event => {
    if (!event.target.closest("a")) return;

    navbar.classList.remove("menu-open");
  });
});

function goToProduct(name) {
  const productPath = window.location.pathname.includes("/pages/") ? "product.html" : "pages/product.html";
  window.location.href = `${productPath}?name=${encodeURIComponent(name)}`;
}

function renderProductImage(container, product, loading = "lazy") {
  if (!container || !product) return;

  const placeholder = document.createElement("span");
  placeholder.textContent = product.name;
  container.innerHTML = "";

  if (!product.imageUrl) {
    container.appendChild(placeholder);
    return;
  }

  const image = document.createElement("img");
  image.src = product.imageUrl;
  image.alt = product.alt;
  image.loading = loading;
  image.decoding = "async";
  image.addEventListener("error", () => {
    container.innerHTML = "";
    container.appendChild(placeholder);
  }, { once: true });

  container.appendChild(image);
}

function renderProducts(containerId, items = products) {
  const container = document.getElementById(containerId);
  if (!container) return;

  container.innerHTML = "";

  items.forEach(p => {
    const div = document.createElement("div");
    div.className = "card";
    div.tabIndex = 0;
    div.setAttribute("role", "link");

    div.innerHTML = `
      <div class="card-image-space"></div>
      <div class="card-copy">
        <h3>${p.cardName}</h3>
      </div>
    `;
    renderProductImage(div.querySelector(".card-image-space"), p);

    div.addEventListener("click", () => goToProduct(p.name));
    div.addEventListener("keydown", event => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        goToProduct(p.name);
      }
    });

    container.appendChild(div);
  });
}

renderProducts("shop-grid");

function setupShopControls() {
  const search = document.getElementById("shopSearch");
  const pagination = document.getElementById("shopPagination");
  const empty = document.getElementById("shopEmpty");
  const grid = document.getElementById("shop-grid");
  const productsPerPage = 21;
  let currentPage = 1;

  if (!search || !pagination || !grid) return;

  function filteredProducts() {
    const query = search.value.trim().toLowerCase();

    return products
      .filter(product => {
        const searchable = [
          product.name,
          product.cardName,
          product.team,
          product.season,
          product.year,
          product.brand,
          product.type
        ].join(" ").toLowerCase();

        return matchesSearch(searchable, query);
      })
      .sort((a, b) => {
        return Number(b.year) - Number(a.year);
      });
  }

  function updateShop(resetPage = false) {
    if (resetPage) currentPage = 1;

    const matches = filteredProducts();
    const pageCount = Math.max(1, Math.ceil(matches.length / productsPerPage));
    currentPage = Math.min(currentPage, pageCount);
    const pageStart = (currentPage - 1) * productsPerPage;
    const visibleProducts = matches.slice(pageStart, pageStart + productsPerPage);

    renderProducts("shop-grid", visibleProducts);
    renderPagination(pageCount, matches.length);

    if (empty) {
      empty.innerText = matches.length === 0 ? "No kits match your search." : "";
    }
  }

  search.addEventListener("input", () => updateShop(true));
  updateShop();

  function matchesSearch(searchable, query) {
    if (!query) return true;

    return query.split(/\s+/).every(term => searchable.includes(term));
  }

  function renderPagination(pageCount, totalMatches) {
    if (totalMatches <= productsPerPage) {
      pagination.innerHTML = "";
      return;
    }

    pagination.innerHTML = `
      <button class="page-button" type="button" data-page="${currentPage - 1}" ${currentPage === 1 ? "disabled" : ""}>Back</button>
      <div class="page-numbers">
        ${Array.from({ length: pageCount }, (_, index) => {
          const page = index + 1;
          return `<button class="page-button page-number ${page === currentPage ? "is-current" : ""}" type="button" data-page="${page}">${page}</button>`;
        }).join("")}
      </div>
      <button class="page-button" type="button" data-page="${currentPage + 1}" ${currentPage === pageCount ? "disabled" : ""}>Next</button>
    `;

    pagination.querySelectorAll("button[data-page]").forEach(button => {
      button.addEventListener("click", () => {
        currentPage = Number(button.dataset.page);
        updateShop();
      });
    });
  }
}

setupShopControls();

document.querySelectorAll(".hero .btn").forEach(button => {
  button.addEventListener("mouseenter", event => {
    const rect = button.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const fromLeft = x;
    const fromRight = rect.width - x;
    const fromTop = y;
    const fromBottom = rect.height - y;
    const closest = Math.min(fromLeft, fromRight, fromTop, fromBottom);

    let moveX = "0px";
    let moveY = "-7px";
    let shadowX = "0px";
    let shadowY = "7px";

    if (closest === fromLeft) {
      moveX = "7px";
      moveY = "0px";
      shadowX = "-7px";
      shadowY = "7px";
    } else if (closest === fromRight) {
      moveX = "-7px";
      moveY = "0px";
      shadowX = "7px";
      shadowY = "7px";
    } else if (closest === fromTop) {
      moveX = "0px";
      moveY = "7px";
      shadowX = "7px";
      shadowY = "-7px";
    }

    button.style.setProperty("--hover-x", moveX);
    button.style.setProperty("--hover-y", moveY);
    button.style.setProperty("--shadow-x", shadowX);
    button.style.setProperty("--shadow-y", shadowY);
  });
});
